import { GoogleGenAI } from "@google/genai";
import axios from "axios";

// Pass the API key explicitly to avoid environment configuration mismatch
const ai = new GoogleGenAI({ apiKey: process.env.GEMINI_API_KEY }); 

/**
 * Service to fetch a file from Cloudinary and analyze it using Gemini 2.5
 * @param {string} fileUrl - The Cloudinary secure URL of the document
 * @param {string} mimeType - The file format (e.g. 'application/pdf', 'image/jpeg')
 * @returns {Promise<string>} - The Markdown text generated by Gemini
 */
export const generateMedicalExplanation = async (fileUrl, mimeType) => {
  try {
    // Fetch the document using Axios as an ArrayBuffer to ensure proper buffer creation
    const response = await axios.get(fileUrl, { responseType: "arraybuffer" });
    const fileBuffer = Buffer.from(response.data);

    // Send the file buffer directly to Gemini 2.5 Flash
    const aiResponse = await ai.models.generateContent({
      model: "gemini-2.5-flash",
      contents: [
        {
          inlineData: {
            data: fileBuffer.toString("base64"),
            mimeType: mimeType
          }
        },
        "You are an expert medical AI system. Analyze this uploaded medical report, prescription, or lab result. Provide a structured, empathetic, and highly accurate analysis. Break down complex medical terms into clear concepts an ordinary patient can understand, interpret critical lab metrics, and clearly highlight warning flags if any values are dangerous. Keep the structure clean with markdown headers and bullet points."
      ]
    });

    // Return the text result back
    return aiResponse.text;

  } catch (error) {
    console.error("Error inside generateMedicalExplanation service function:", error);
    throw error;
  }
};